params.query:
-- Drop existing foreign key constraint
ALTER TABLE recall_images DROP CONSTRAINT IF EXISTS recall_images_recall_id_fkey;

-- Add foreign key with cascade delete
ALTER TABLE recall_images 
ADD CONSTRAINT recall_images_recall_id_fkey 
FOREIGN KEY (recall_id) 
REFERENCES recalls(id) 
ON DELETE CASCADE;

-- Rename image_url to image_path if it exists
DO $$ 
BEGIN
  IF EXISTS (
    SELECT 1 FROM information_schema.columns 
    WHERE table_name = 'recall_images' AND column_name = 'image_url'
  ) THEN
    ALTER TABLE recall_images RENAME COLUMN image_url TO image_path;
  END IF;
END $$;
